import json,pathlib
p=pathlib.Path('.book-work/planetaryskyunderstandingthecolorsaboveus-v1-7d866fc6ab2a/translations/ro/full/chunks')
t={
't000042':'''Poluarea atmosferică influențează puternic aspectul cerului, diferiții poluanți schimbându-i culoarea, limpezimea și frumusețea. O categorie importantă este materia sub formă de particule în suspensie, alcătuită din particule solide sau lichide foarte mici. Ele pot proveni din surse naturale și din activități omenești. Praful, polenul și sarea marină sunt surse naturale; funinginea și alte produse ale arderii provin, între altele, din vehicule, industrie și arderea biomasei. Dimensiunea și compoziția particulelor variază mult, influențând interacțiunea lor cu lumina și, prin urmare, culoarea cerului.''',
't000043':'''Alți poluanți importanți sunt oxizii de azot, emiși mai ales de gazele de eșapament și de activitățile industriale. Ei au un rol esențial în formarea ozonului la nivelul solului și pot duce la apariția unor poluanți secundari care contribuie la smog. Prezența lor afectează nu doar calitatea aerului, ci și împrăștierea luminii și, implicit, aspectul cerului, mai ales în orașe. Dioxidul de sulf este un alt poluant important, provenit în principal din arderea combustibililor fosili care conțin sulf, precum cărbunele și petrolul. Ajuns în atmosferă, el poate reacționa cu alte substanțe și forma aerosoli de sulfat, care modifică semnificativ împrăștierea luminii. Aceste particule pot face cerul să pară mai alb și pot contribui la formarea norilor, influențând vremea și vizibilitatea.''',
't000044':'''Dioxidul de sulf poate contribui și la ploaia acidă, cu alte efecte asupra mediului. Ozonul de la nivelul solului este un caz aparte. În stratosferă, ozonul este benefic, protejând viața terestră de radiația ultravioletă nocivă; aproape de sol devine însă un poluant dăunător. El se formează prin reacțiile chimice dintre oxizii de azot și compușii organici volatili în prezența luminii solare. Poate afecta sănătatea oamenilor și mediul. La nivelul aspectului, concentrațiile mari de ozon pot crea pâclă și pot estompa culorile zilei. În cele din urmă, aerosolii formează o categorie largă de particule solide și lichide suspendate în aer, cuprinzând fum, praf, stropi de apă marină și emisii industriale.''',
't000045':'''Aerosolii provin din surse diferite, de la erupții vulcanice la arderea combustibililor fosili și agricultură. În funcție de compoziție și mărime, ei pot influența puternic împrăștierea luminii, pâcla, formarea norilor și culoarea generală a cerului. Poluanții atmosferici au astfel efecte importante asupra aspectului cerului. Materia în suspensie, oxizii de azot, dioxidul de sulf și ozonul de la sol interacționează fiecare altfel cu lumina și produc rezultate vizuale diferite. Înțelegerea lor este esențială pentru abordarea problemelor de calitate a aerului și a consecințelor asupra sănătății mediului, climei și bunăstării publice. Studierea lor ne ajută să apreciem complexitatea interacțiunilor atmosferice și să căutăm soluții pentru un aer mai curat.''',
't000046':'''Poluanții schimbă semnificativ felul în care lumina este împrăștiată în atmosferă, producând modificări vizibile ale culorii și limpezimii cerului. Mecanismele diferă în funcție de dimensiunea și compoziția particulelor. Împrăștierea Mie predomină când aerul conține particule mai mari, precum cele din smog. Spre deosebire de împrăștierea Rayleigh, care depinde mult de lungimea de undă și afectează în principal lumina cu lungime scurtă, procesul Mie este mai puțin selectiv și influențează mai uniform lungimile mari. Cerul apare atunci adesea albicios sau cenușiu, mai ales în zonele urbane foarte poluate. În zilele cu smog, de pildă, vizibilitatea poate scădea mult, iar albastrul viu este înlocuit de o nuanță ternă. Efectul influențează nu doar peisajul, ci și starea psihică a celor care asociază cerul senin cu vremea plăcută.''',
't000047':'''Unii poluanți, mai ales particulele întunecate precum funinginea rezultată din ardere, absorb lumina în întregul spectru vizibil. Cerul poate deveni mai întunecat și mai șters, mai ales în perioadele de poluare puternică. În regiunile cu industrie intensă sau incendii de vegetație frecvente, acumularea de funingine poate reduce mult pătrunderea luminii, lăsând un cer lipsit de strălucirea unui aer curat. Efectul se vede deosebit de clar în timpul incendiilor de pădure, când fumul abundent întunecă cerul. În mod interesant, particulele în suspensie pot intensifica și culorile răsăriturilor și apusurilor. Când Soarele este aproape de orizont, lumina trece printr-un strat mai gros de atmosferă și întâlnește mai multe particule. Interacțiunea împrăștie lungimile de undă scurte, albastre și verzi, în timp ce roșul și portocaliul ajung să domine.''',
't000048':'''Prin urmare, culorile răsăriturilor și apusurilor pot deveni mai vii și mai impresionante, creând uneori priveliști frumoase chiar și în medii poluate. Acest efect dublu arată că poluanții pot în același timp să strice și să îmbogățească experiența vizuală a cerului. Amestecul de particule și gaze poate forma pâclă, care reduce vizibilitatea și schimbă culoarea generală. Pâcla apare când umezeala și poluanții se combină, împrăștiind lumina și creând un aspect difuz, cenușiu. Este des întâlnită în orașe în lunile calde, când umiditatea crește. Ea poate ascunde peisajele îndepărtate și poate estompa contururile, afectând atât priveliștile naturale, cât și silueta orașelor. Consecințele merg însă dincolo de estetică.''',
't000049':'''Schimbarea împrăștierii luminii din cauza poluanților poate afecta clima, fotosinteza plantelor și sănătatea oamenilor. Reducerea luminii care ajunge la sol poate perturba ecosistemele locale, de la creșterea plantelor la comportamentul animalelor. Poluanții au, așadar, un rol important în modificarea împrăștierii luminii în atmosferă. Procese precum împrăștierea Mie și absorbția luminii de particulele întunecate pot produce efecte de la ceruri terne la apusuri spectaculoase. Interacțiunea poluanților cu lumina solară schimbă nu numai aspectul cerului, ci are și implicații mai ample pentru sănătatea mediului și dinamica ecosistemelor. Înțelegerea acestor relații este necesară pentru îmbunătățirea calității aerului și limitarea efectelor asupra mediului și oamenilor.''',
't000050':'''Calitatea aerului are un efect direct și vizibil asupra cerului. Poluarea puternică poate reduce mult vizibilitatea, făcând obiectele îndepărtate să pară învăluite în pâclă. Aerul curat este asociat, de obicei, cu un cer de un albastru intens, în timp ce aerul poluat îl poate face bleu pal, alb sau chiar maroniu. Paradoxal, o poluare moderată poate produce apusuri mai vii, prin împrăștierea sporită a luminii roșii și portocalii. Cerurile orașelor arată adesea altfel decât cele rurale, în primul rând din cauza nivelului mai mare de poluare. Expunerea îndelungată la poluare cronică poate duce la schimbări persistente ale culorii locale și ale vizibilității. Relația dintre poluare și cer are aplicații practice în monitorizarea aerului și în sănătatea publică.''',
't000051':'''Mulți oameni recunosc instinctiv schimbările cerului ca semne ale calității aerului, ceea ce poate crește atenția acordată poluării. Studierea acestor efecte îi ajută și pe cercetătorii atmosferei să înțeleagă interacțiunile complexe dintre poluanți și radiația solară, importante pentru modelele climatice și pentru anticiparea consecințelor activităților omenești. Cum problemele de calitate a aerului persistă în lume, culoarea cerului rămâne un indiciu vizibil al stării atmosferei și amintește de importanța aerului curat atât pentru frumusețea priveliștii, cât și pentru sănătate.''',
't000052':'Capitolul al șaselea — Efectele climei și vremii asupra cerului'
}
seen=set()
for n in (7,8):
 f=p/f'{n:04}.json';d=json.loads(f.read_text())
 for x in d['segments']:
  assert not x['translation'] and x['id'] in t;x['translation']=t[x['id']];seen.add(x['id'])
 f.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
assert seen==set(t)
print('Translated',len(seen))
